public void run()
{
    SalesTable salesTableLocal = this.salesTable();

    if (salesTableLocal)
    {
        METVendParameters vendParameters;

        select firstonly SalesOrderType from vendParameters;

        CustVendorBlocked   blockStatus   = CustTable::find(salesTableLocal.CustAccount).Blocked;

        // Verify if the CustAccount is blocked post sales invoice should not trigger
        if (salesTableLocal.METSalesOrderType != vendParameters.SalesOrderType && blockStatus == CustVendorBlocked::METSalesinvoice)
        {
            throw warning(strFmt("@SYS18389", salesTableLocal.CustAccount, enum2Str(blockStatus)));
        }

        if (this.shouldSplitCreditInvoice(salesTableLocal)
                && this.hasNegativeAndPositiveLines(salesTableLocal))
        {            
            // Create and post credit note
            this.createAndPostCreditNote(salesTableLocal);     
        }  
    } 

    next run(); 
}

/// <summary>
/// Determines if the sales invoice should be split into credit and tax invoices based on sales type, original invoice, and order type settings.    
/// </summary>
/// <param name = "_salesTable"></param>
/// <returns>True if the invoice should be split; otherwise, false.</returns>
public boolean shouldSplitCreditInvoice(SalesTable _salesTable)
{
    METSalesTable       metSalesTable =  METSalesTable::findByRefRecId(_salesTable.RecId);
    METSalesOrderTypes  metSalesOrderTypes = METSalesOrderTypes::find(_salesTable.METSalesOrderType);

    return _salesTable.SalesType == SalesType::Sales
            && strLen(metSalesTable.OriginalSalesId) > 0
            && metSalesOrderTypes.SplitCreditInvoice == NoYes::Yes;
}

/// <summary>
/// Checks if the sales table has both negative and positive line amounts in the associated parameter lines.
/// </summary>
/// <param name = "_salesTable"></param>
/// <returns></returns>
public boolean hasNegativeAndPositiveLines(SalesTable _salesTable)
{
    salesParmTable  salesParmTable;
    SalesParmLine   salesParmLine;

    select firstonly salesParmTable
    where salesParmTable.ParmId == this.parmId()
        && salesParmTable.SalesId == _salesTable.SalesId;

    if (!salesParmTable.RecId)
    {
        return false;
    }

    // Check for negative line
    select firstonly RecId from salesParmLine
        where salesParmLine.ParmId == salesParmTable.ParmId
            && salesParmLine.TableRefId == salesParmTable.TableRefId
            && salesParmLine.LineAmount < 0;

    if (!salesParmLine.RecId)
    {
        return false;
    }

    // Check for positive line
    select firstonly RecId from salesParmLine
        where salesParmLine.ParmId == salesParmTable.ParmId
            && salesParmLine.TableRefId == salesParmTable.TableRefId
            && salesParmLine.LineAmount > 0;

    if (!salesParmLine.RecId)
    {
        return false;
    }

    return true;
}

/// <summary>
/// Creates and posts a credit note for the specified sales table record by processing all negative quantity sales lines.
/// </summary>
/// <param name = "_salesTable"></param>
private void createAndPostCreditNote(SalesTable _salesTableLocal)
{
    salesFormLetter         salesFormLetter;
    salesFormletterParmData salesFormLetterParmData;
    salesParmUpdate         salesParmUpdate;
    salesParmTable          salesParmTable;
    salesParmLine           salesParmLine;
    SalesLine               saleslineLocal;
    MarkupTrans             markupTransHeader;  
    List                    taxInvoiceHeaderCharges = new List(Types::Record);

    try
    {
        taxInvoiceHeaderCharges = this.prepareTaxInvoiceData(_salesTableLocal);

        ttsbegin;
        salesFormLetterParmData = salesFormletterParmData::newData(DocumentStatus::Invoice, VersioningUpdateType::Initial);

        salesFormLetterParmData.parmOnlyCreateParmUpdate(true);
        salesFormLetterParmData.createData(false);
        salesParmUpdate = salesFormLetterParmData.parmParmUpdate();

        // Prepare parameter data for invoice posting
        salesParmTable.clear();
        salesParmTable.initFromSalesTable(_salesTableLocal);
        salesParmTable.TransDate                = SystemDateGet();
        salesParmTable.Ordering                 = DocumentStatus::Invoice;
        salesParmTable.ParmJobStatus            = ParmJobStatus::Waiting;
        salesParmTable.ParmId                   = salesParmUpdate.ParmId;
        salesParmTable.insert();


        // Filter and add only negative quantity lines
        while select saleslineLocal
            where saleslineLocal.SalesId == _salesTableLocal.SalesId
            && saleslineLocal.SalesQty < 0
        {
            salesParmLine.InitFromsalesLine(saleslineLocal);
            salesParmLine.DeliverNow    = saleslineLocal.SalesQty;
            salesParmLine.ParmId        = salesParmTable.ParmId;
            salesParmLine.TableRefId    = salesParmTable.TableRefId;
            salesParmLine.setQty(DocumentStatus::Invoice, true, true); 
            salesParmLine.setLineAmount(saleslineLocal);
            salesParmLine.insert();
        }  
        ttscommit;

        // Post the credit note
        salesFormLetter = salesFormLetter::construct(DocumentStatus::Invoice);
        salesFormLetter.transDate(SystemDateGet());
        salesFormLetter.proforma(false);
        salesFormLetter.specQty(salesUpdate::DeliverNow);
        salesFormLetter.salesTable(_salesTableLocal);
        salesFormLetter.parmId(salesParmTable.ParmId);
        salesFormLetter.salesParmUpdate(salesFormLetterParmData.parmParmUpdate());
        salesFormLetter.printFormLetter(true);
        salesFormLetter.run();

        this.addTaxInvoiceHeaderCharges(taxInvoiceHeaderCharges);        
    }
    catch (Exception::Error)
    {
        ttsabort;
        throw error("@MET:FailedToCreateCN" + _salesTableLocal.SalesId);
    }
}

/// <summary>
/// Prepares tax invoice header charges for the specified sales table by collecting positive MarkupTrans records, unlinks them, and removes negative lines from the parameter table. Returns a list of MarkupTrans records for later processing.  
/// </summary>
/// <param name = "_salesTable"></param>
/// <returns></returns>
public list prepareTaxInvoiceData(SalesTable _salesTable)
{
    MarkupTrans     markupTransHeader;
    salesParmTable  salesParmTable;
    salesParmLine   salesParmLine;
    List            taxInvoiceHeaderCharges = new List(Types::Record);

    // Select records into the list
    while select markupTransHeader
        where markupTransHeader.TransTableId == tableNum(SalesTable)
        && markupTransHeader.TransRecId == _salesTable.RecId
        && markupTransHeader.Value > 0
    {
        taxInvoiceHeaderCharges.addEnd(markupTransHeader);
    }

    ttsbegin;
    // Unlink positive markup transaction.
    delete_from markupTransHeader
        where markupTransHeader.TransTableId == tableNum(SalesTable)
            && markupTransHeader.TransRecId == _salesTable.RecId
            && markupTransHeader.Value > 0;

    select firstonly salesParmTable
        where salesParmTable.ParmId == this.parmId()
            && salesParmTable.SalesId == _salesTable.SalesId;

    if (salesParmTable.RecId)
    {
        // Remove negative lines from original parameter table.
        delete_from salesParmLine
            where salesParmLine.ParmId == salesParmTable.ParmId
                && salesParmLine.TableRefId == salesParmTable.TableRefId
                && salesParmLine.LineAmount < 0;
    }
    ttscommit;

    return taxInvoiceHeaderCharges;
}

/// <summary>
/// Adds tax invoice header charges by inserting each MarkupTrans record from the provided list.
/// </summary>
/// <param name = "_taxInvoiceHeaderCharges"></param>
public void addTaxInvoiceHeaderCharges(List _taxInvoiceHeaderCharges)
{
    MarkupTrans     markupTransHeader;
    ListEnumerator  enumerator = _taxInvoiceHeaderCharges.getEnumerator();

    ttsbegin;
    while (enumerator.moveNext())
    {
        markupTransHeader = enumerator.current();
        markupTransHeader.insert();
    }
    ttscommit;    
}
